package service;

import domain.FxQuote;
import infra.FxqClient;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /** Vendor source that gives the day's settlement value, also on vendor closed days. */
    private static final int SETTLEMENT_SOURCE = 2;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, BigDecimal> settlementCache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Published quote on the default source. Used by the customer rate board. */
    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * On a vendor closed day the default source only carries the previous business day's value (tagged "~N"),
     * so that day's value is requested from the settlement source instead.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return settlementCache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            String line = client.rate(pair, date);
            if (FxqClient.lagged(line)) {
                vendorCalls++;
                line = client.rate(pair, date, SETTLEMENT_SOURCE);
            }
            return FxqClient.parse(line).rate();
        });
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}
